<template>
  <BioNexusDialog ref="dialog" size="fullscreen" kicker="Laboratorio experimental" title="Disenador matricial de resultados" :subtitle="exam?.description || ''" body-flush body-scroll="hidden" :prevent-close="dirty" @before-close="requestClose" @close="handleClosed">
    <template #header-actions><span class="pilot-badge">Formato en Bio Nexus</span></template>
    <section class="grid-designer-shell">
      <nav class="grid-designer-toolbar" aria-label="Herramientas del disenador matricial">
        <button type="button" @mousedown.prevent @click="mergeSelection"><BioNexusIcon name="cell_merge" :size="18" />Combinar</button>
        <button type="button" @mousedown.prevent @click="unmergeSelection"><BioNexusIcon name="call_split" :size="18" />Separar</button>
        <button type="button" @mousedown.prevent @click="toggleBold"><strong>B</strong>Negrita</button>
        <button type="button" @mousedown.prevent @click="toggleUnderline"><u>U</u>Subrayado</button>
        <select class="format-select" title="Tamano de fuente" aria-label="Tamano de fuente" @change="applyFontSize"><option value="11">11 px</option><option value="12" selected>12 px</option><option value="14">14 px</option><option value="16">16 px</option><option value="18">18 px</option><option value="22">22 px</option></select><select class="format-select" title="Altura de fila" aria-label="Altura de fila" @change="applyRowHeightPreset"><option value="">Altura...</option><option value="22">Compacta 22 px</option><option value="32">Normal 32 px</option><option value="44">Amplia 44 px</option><option value="custom">Personalizada...</option></select><button type="button" title="Ajustar altura al contenido" aria-label="Ajustar altura al contenido" @mousedown.prevent @click="fitSelectedRowsToContent"><BioNexusIcon name="height" :size="18" /></button>
        <button type="button" title="Alinear a la izquierda" @mousedown.prevent @click="applyStyle('text-align','left')"><BioNexusIcon name="format_align_left" :size="18" /></button>
        <button type="button" title="Centrar" @mousedown.prevent @click="applyStyle('text-align','center')"><BioNexusIcon name="format_align_center" :size="18" /></button>
        <button type="button" title="Alinear a la derecha" @mousedown.prevent @click="applyStyle('text-align','right')"><BioNexusIcon name="format_align_right" :size="18" /></button>
        <button type="button" title="Alinear arriba" @mousedown.prevent @click="applyStyle('vertical-align','top')"><BioNexusIcon name="vertical_align_top" :size="18" /></button><button type="button" title="Centrar verticalmente" @mousedown.prevent @click="applyStyle('vertical-align','middle')"><BioNexusIcon name="vertical_align_center" :size="18" /></button><button type="button" title="Alinear abajo" @mousedown.prevent @click="applyStyle('vertical-align','bottom')"><BioNexusIcon name="vertical_align_bottom" :size="18" /></button>
        <label class="grid-color-control" title="Color del texto"><BioNexusIcon name="format_color_text" :size="18" /><input type="color" value="#111111" aria-label="Color del texto" @input="applyColor('color',$event)" /></label>
        <label class="grid-color-control" title="Color de fondo"><BioNexusIcon name="format_color_fill" :size="18" /><input type="color" value="#ffffff" aria-label="Color de fondo" @input="applyColor('background-color',$event)" /></label>
        <select class="format-select" title="Bordes" aria-label="Bordes" @change="applyBorderChoice"><option value="">Bordes...</option><option value="all">Todos</option><option value="outer">Exterior</option><option value="top">Superior</option><option value="bottom">Inferior</option><option value="left">Izquierdo</option><option value="right">Derecho</option><option value="none">Sin bordes</option></select>
        <button type="button" @mousedown.prevent @click="configureField"><BioNexusIcon name="data_object" :size="18" />Configurar campo</button>
        <button type="button" title="Deshacer" aria-label="Deshacer" @mousedown.prevent @click="worksheet?.undo()"><BioNexusIcon name="undo" :size="18" /></button>
        <button type="button" title="Rehacer" aria-label="Rehacer" @mousedown.prevent @click="worksheet?.redo()"><BioNexusIcon name="redo" :size="18" /></button>
        <button type="button" class="preview-button" :class="{active:tab==='preview'}" @mousedown.prevent @click="tab=tab==='design'?'preview':'design'"><BioNexusIcon name="preview" :size="18" />{{ tab==='design' ? 'Vista previa' : 'Volver al diseno' }}</button>
      </nav>
      <section v-show="tab==='design'" class="grid-designer-workspace" @pointerdown.capture="handleWorkspacePointerDown">
        <aside class="grid-designer-side">
          <strong>Formato de la fila seleccionada</strong><small>Selecciona una celda de la fila y aplica una estructura. No se agregan filas nuevas.</small>
          <button type="button" class="row-template" @click="applyRowFormat('full')"><b>Una celda completa</b><small>Combina toda la fila seleccionada</small><i><span class="span-4"></span></i></button>
          <button type="button" class="row-template" @click="applyRowFormat('two')"><b>Dos celdas iguales</b><small>Distribucion 50 / 50</small><i><span class="span-2"></span><span class="span-2"></span></i></button>
          <button type="button" class="row-template" @click="applyRowFormat('three')"><b>Tres celdas</b><small>Distribucion equilibrada</small><i><span></span><span></span><span class="span-2"></span></i></button>
          <button type="button" class="row-template" @click="applyRowFormat('standard')"><b>Resultado estandar</b><small>Conserva cuatro celdas independientes</small><i><span></span><span></span><span></span><span></span></i></button>
          <button type="button" class="row-template" @click="applyRowFormat('reference')"><b>Valor referencial</b><small>Contenido principal en la ultima columna</small><i><span class="span-3"></span><span></span></i></button>
          <button type="button" class="row-template" @click="applyRowFormat('observation')"><b>Observaciones</b><small>Etiqueta y area amplia de captura</small><i><span></span><span class="span-3"></span></i></button>
          <button type="button" class="row-template antibiogram-template" @click="applyAntibiogramModule"><b>Antibiograma</b><small>Bloque dinamico de cultivo, microorganismos, sensibilidad y MIC</small><i><span class="span-4"></span></i></button><span>Doble clic para editar una celda.</span><span>Arrastra encabezados para ajustar ancho y alto.</span><span>Selecciona un rango para combinar o dar formato.</span>
          <section class="field-summary"><strong>Campos del reporte</strong><article v-for="field in fieldList" :key="field.key"><b>{{ field.label }}</b><small>{{ field.key }} | {{ field.source==='formula' ? 'Calculado' : 'Manual' }}</small><code v-if="field.source==='formula'">{{ field.formula }}</code></article><span v-if="fieldList.length===0">Aun no hay campos configurados.</span></section>
          <small class="local-note">Persistencia temporal por examen en este navegador. No modifica bionexus.</small>
        </aside>
        <div class="grid-sheet-frame"><div ref="sheetHost" class="grid-sheet-host bio-nexus-grid-sheet-scroll"></div></div>
      </section>
      <section v-if="tab==='preview'" class="grid-preview-scroll"><article class="grid-preview-page"><table><colgroup><col v-for="(width,index) in previewWidths" :key="index" :style="{width:width+'px'}" /></colgroup><tbody><tr v-for="(row,rowIndex) in previewRows" :key="rowIndex" :style="{height:(previewRowHeights[rowIndex] || 32)+'px'}"><td v-for="cell in row" :key="cell.name" :colspan="cell.colspan" :rowspan="cell.rowspan" :style="cell.style"><template v-if="moduleAt(cell.name)"><section class="antibiogram-preview-block"><strong>Modulo antibiograma</strong><small>El contenido dinamico se completa al reportar el examen.</small></section></template><template v-else>{{ previewValue(cell.value) }}</template></td></tr></tbody></table></article></section>
      <BioNexusDialog ref="fieldDialog" :size="wizardStep===3?'large':'compact'" kicker="Contenido de la celda" :title="fieldDialogTitle" :subtitle="fieldDialogSubtitle">
        <section class="field-wizard"><nav class="wizard-steps" aria-label="Pasos del campo"><span v-for="step in 4" :key="step"  :class="{active:wizardStep===step,done:wizardStep>step,skipped:step===3&&fieldDraft.source!=='formula'}">{{ step }}</span></nav><section v-if="wizardStep===1" class="wizard-panel"><h3>Tipo de celda</h3><p>Selecciona como se obtendra el resultado.</p><label class="wizard-choice"><input v-model="fieldDraft.source" type="radio" value="text" /><span><strong>Texto</strong><small>Permite registrar contenido de texto libre.</small></span></label><label class="wizard-choice"><input v-model="fieldDraft.source" type="radio" value="numeric" /><span><strong>Numerico</strong><small>Permite registrar un valor numerico con decimales configurables.</small></span></label><label class="wizard-choice"><input v-model="fieldDraft.source" type="radio" value="formula" /><span><strong>Formula</strong><small>Bio Nexus calcula el resultado a partir de otros campos.</small></span></label><label class="wizard-choice"><input v-model="fieldDraft.source" type="radio" value="autocomplete" /><span><strong>Autocompletacion</strong><small>Permite seleccionar un valor desde una lista de opciones configuradas.</small></span></label></section><section v-else-if="wizardStep===2" class="wizard-panel"><h3>Identidad y formato</h3><BioNexusFormField label="Etiqueta" field-id="pilot-field-label"><input id="pilot-field-label" v-model="fieldDraft.label" class="bio-nexus-field" placeholder="Hemoglobina" @input="syncSuggestedFieldKey" /></BioNexusFormField><BioNexusFormField label="Identificador" field-id="pilot-field-key"><input id="pilot-field-key" v-model="fieldDraft.key" class="bio-nexus-field" placeholder="hemoglobina" @input="markFieldKeyEdited" /></BioNexusFormField><BioNexusFormField v-if="fieldDraft.source==='formula'" label="Tipo de dato resultante" field-id="pilot-field-data-type"><select id="pilot-field-data-type" v-model="fieldDraft.dataType" class="bio-nexus-field"><option value="numeric">Numerico</option><option value="text">Texto</option><option value="boolean">Si / No</option></select></BioNexusFormField><BioNexusFormField v-if="fieldDraft.source==='numeric' || (fieldDraft.source==='formula' && fieldDraft.dataType==='numeric')" label="Decimales" field-id="pilot-field-decimals"><input id="pilot-field-decimals" v-model.number="fieldDraft.decimals" class="bio-nexus-field" type="number" min="0" max="6" /></BioNexusFormField><section v-if="fieldDraft.source==='autocomplete'" class="autocomplete-builder"><strong>Opciones de autocompletacion</strong><p>Estas opciones apareceran en una lista desplegable al reportar el examen.</p><div v-for="(option,index) in fieldDraft.options" :key="index" class="autocomplete-option"><input v-model="fieldDraft.options[index]" class="bio-nexus-field" :aria-label="'Opcion '+(index+1)" /><button type="button" title="Eliminar opcion" @click="removeAutocompleteOption(index)"><BioNexusIcon name="delete" :size="17" /></button></div><button type="button" class="add-autocomplete-option" @click="addAutocompleteOption">Agregar opcion</button></section></section><section v-else-if="wizardStep===3" class="wizard-panel"><template v-if="fieldDraft.source==='formula'"><h3>Construir formula</h3><p>Agrega campos y operaciones. No se usan coordenadas de celdas.</p><div class="formula-mode-choice"><strong>Como se determina el calculo?</strong><label><input v-model="fieldDraft.formulaMode" type="radio" value="single" @change="ensureFormulaModeState" />Una sola formula</label><label><input v-model="fieldDraft.formulaMode" type="radio" value="selection" @change="ensureFormulaModeState" />Una formula por cada opcion seleccionada</label><label><input v-model="fieldDraft.formulaMode" type="radio" value="rules" @change="ensureFormulaModeState" />Reglas condicionales</label></div><section v-if="fieldDraft.formulaMode==='rules'" class="derived-rules"><header><div><strong>Reglas condicionales</strong><p>Se aplica la primera regla que coincida.</p></div><button type="button" @click="addDerivedRule">Agregar regla</button></header><article v-for="(rule,index) in fieldDraft.rules" :key="rule.uid" class="derived-rule"><div class="rule-heading"><strong>Regla {{ index + 1 }}</strong><div><button type="button" :disabled="index===0" @click="moveDerivedRule(index,-1)">Subir</button><button type="button" :disabled="index===fieldDraft.rules.length-1" @click="moveDerivedRule(index,1)">Bajar</button><button type="button" @click="removeDerivedRule(index)">Eliminar</button></div></div><div class="rule-condition"><BioNexusFormField label="Campo evaluado" :field-id="'derived-field-'+index"><select :id="'derived-field-'+index" v-model="rule.fieldKey" class="bio-nexus-field" @change="normalizeDerivedRule(rule)"><option value="">Seleccionar campo</option><option v-for="field in availableFormulaFields" :key="field.key" :value="field.key">{{ field.label }} ({{ field.key }})</option></select></BioNexusFormField><BioNexusFormField label="Condicion" :field-id="'derived-operator-'+index"><select :id="'derived-operator-'+index" v-model="rule.operator" class="bio-nexus-field"><option v-for="operator in operatorsForRule(rule)" :key="operator.value" :value="operator.value">{{ operator.label }}</option></select></BioNexusFormField><BioNexusFormField v-if="operatorNeedsValue(rule.operator)" label="Valor de comparacion" :field-id="'derived-compare-'+index"><template v-if="fieldStore[rule.fieldKey]?.source==='autocomplete'"><select :id="'derived-compare-'+index" v-model="rule.compareValue" class="bio-nexus-field"><option value="">Seleccionar opcion</option><option v-for="option in fieldStore[rule.fieldKey]?.options || []" :key="option" :value="option">{{ option }}</option></select></template><input v-else :id="'derived-compare-'+index" v-model="rule.compareValue" class="bio-nexus-field" /></BioNexusFormField></div><div class="rule-result"><BioNexusFormField label="Resultado" :field-id="'derived-result-type-'+index"><select :id="'derived-result-type-'+index" v-model="rule.resultType" class="bio-nexus-field"><option value="text">Escribir texto</option><option value="number">Usar numero</option><option value="field">Copiar otro campo</option><option value="formula">Calcular formula</option><option value="empty">Dejar vacio</option></select></BioNexusFormField><BioNexusFormField v-if="rule.resultType==='text' || rule.resultType==='number'" label="Valor resultante" :field-id="'derived-result-'+index"><input :id="'derived-result-'+index" v-model="rule.resultValue" class="bio-nexus-field" /></BioNexusFormField><BioNexusFormField v-if="rule.resultType==='field'" label="Campo a copiar" :field-id="'derived-copy-'+index"><select :id="'derived-copy-'+index" v-model="rule.resultValue" class="bio-nexus-field"><option value="">Seleccionar campo</option><option v-for="field in availableFormulaFields" :key="field.key" :value="field.key">{{ field.label }}</option></select></BioNexusFormField><BioNexusFormField v-if="rule.resultType==='formula'" label="Formula resultante" :field-id="'derived-formula-'+index"><textarea :id="'derived-formula-'+index" v-model="rule.resultValue" class="bio-nexus-field formula-editor" rows="2"></textarea></BioNexusFormField></div></article><section class="default-derived-result"><strong>Resultado si ninguna regla coincide</strong><select v-model="fieldDraft.defaultResult.type" class="bio-nexus-field"><option value="empty">Dejar vacio</option><option value="text">Escribir texto</option><option value="number">Usar numero</option><option value="field">Copiar otro campo</option><option value="formula">Calcular formula</option></select><input v-if="fieldDraft.defaultResult.type==='text' || fieldDraft.defaultResult.type==='number'" v-model="fieldDraft.defaultResult.value" class="bio-nexus-field" /><select v-if="fieldDraft.defaultResult.type==='field'" v-model="fieldDraft.defaultResult.value" class="bio-nexus-field"><option value="">Seleccionar campo</option><option v-for="field in availableFormulaFields" :key="field.key" :value="field.key">{{ field.label }}</option></select><textarea v-if="fieldDraft.defaultResult.type==='formula'" v-model="fieldDraft.defaultResult.value" class="bio-nexus-field formula-editor" rows="2"></textarea></section><div class="derived-rule-actions"><button type="button" @click="validateDerivedRules">Validar reglas</button><button type="button" @click="openRuleTester">Probar reglas</button></div></section><div v-else-if="fieldDraft.formulaMode==='selection'" class="selection-formulas"><BioNexusFormField label="Campo que determina el calculo" field-id="pilot-selector-field"><select id="pilot-selector-field" v-model="fieldDraft.selectorFieldKey" class="bio-nexus-field" @change="syncSelectionCases"><option value="">Seleccionar Autocompletacion</option><option v-for="field in autocompleteFormulaFields" :key="field.key" :value="field.key">{{ field.label }}</option></select></BioNexusFormField><p v-if="autocompleteFormulaFields.length===0" class="formula-guidance">Primero crea un campo de Autocompletacion con sus opciones.</p><article v-for="item in selectionCaseItems" :key="item.option" class="selection-case"><strong>{{ item.option }}</strong><textarea v-model="fieldDraft.cases[item.option]" class="bio-nexus-field formula-editor" rows="2" :aria-label="'Formula para '+item.option"></textarea><div class="case-actions"><button type="button" @click="formatCaseFormula(item.option)">Formatear</button><button type="button" @click="validateCaseFormula(item.option)">Validar</button><button type="button" @click="openFormulaTester(item.option)">Probar</button></div></article></div><div v-else class="formula-builder formula-builder-wide"><aside class="formula-field-list"><strong>Campos calculables</strong><span v-if="calculationFields.length===0" class="formula-field-empty">Primero crea un campo Numerico o Formula.</span><button v-for="field in calculationFields" :key="field.key" type="button" :title="'Doble clic para insertar '+field.key" @dblclick="insertFieldAtCursor(field.key)"><b>{{ field.label }}</b><small>{{ field.key }}</small></button></aside><div class="formula-operators"><button v-for="operator in formulaOperators" :key="operator" type="button" @click="addFormulaToken(operator)">{{ operator }}</button><span class="formula-operator-separator"></span><button type="button" title="Envolver toda la formula en parentesis" aria-label="Envolver toda la formula en parentesis" @click="wrapWholeFormula"><BioNexusIcon name="data_object" :size="17" /></button><button type="button" title="Formatear formula" aria-label="Formatear formula" @click="formatCurrentFormula"><BioNexusIcon name="format_align_left" :size="17" /></button><button type="button" title="Validar formula" aria-label="Validar formula" @click="validateCurrentFormula"><BioNexusIcon name="check_circle" :size="17" /></button><button type="button" title="Probar formula" aria-label="Probar formula" @click="openFormulaTester()"><BioNexusIcon name="play_circle" :size="17" /></button><button type="button" class="formula-clear-icon" title="Limpiar formula" aria-label="Limpiar formula" @click="fieldDraft.formula=''"><BioNexusIcon name="delete_sweep" :size="17" /></button></div><div class="formula-expression"><strong>Formula resultante</strong><textarea ref="formulaEditor" v-model="fieldDraft.formula" class="bio-nexus-field formula-editor" rows="5" spellcheck="false" aria-label="Formula resultante"></textarea></div></div></template><template v-else><h3>Sin formula</h3><p>Este tipo de campo no requiere una expresion de calculo.</p></template></section><section v-else class="wizard-panel"><h3>Resumen</h3><dl><dt>Celda</dt><dd>{{ selectedCellName }}</dd><dt>Tipo</dt><dd>{{ fieldTypeLabel }}</dd><dt>Etiqueta</dt><dd>{{ fieldDraft.label }}</dd><dt>Identificador</dt><dd>{{ fieldDraft.key }}</dd><template v-if="fieldDraft.source==='formula'"><dt>Formula</dt><dd><code>{{ fieldDraft.formula }}</code></dd></template><dt>Decimales</dt><dd>{{ fieldDraft.decimals }}</dd></dl></section><div v-if="fieldError" class="bio-nexus-message bio-nexus-message-error">{{ fieldError }}</div></section>
        <template #footer><button type="button" class="bio-nexus-action bio-nexus-action-secondary" @click="fieldDialog?.close()">Cancelar</button><button v-if="wizardStep>1" type="button" class="bio-nexus-action bio-nexus-action-secondary" @click="wizardBack">Atras</button><button v-if="wizardStep<4" type="button" class="bio-nexus-action bio-nexus-action-primary" @click="wizardNext">Siguiente</button><button v-else type="button" class="bio-nexus-action bio-nexus-action-primary" @click="saveField">Crear campo</button></template>
      </BioNexusDialog><BioNexusDialog ref="ruleTestDialog" size="compact" kicker="Validacion local" title="Probar reglas" :subtitle="fieldDraft.label"><section class="rule-test-body"><BioNexusFormField v-for="field in ruleTestInputs" :key="field.key" :label="field.label" :field-id="'rule-test-'+field.key"><select v-if="field.source==='autocomplete'" :id="'rule-test-'+field.key" v-model="ruleTestValues[field.key]" class="bio-nexus-field"><option value="">Seleccionar</option><option v-for="option in field.options" :key="option" :value="option">{{ option }}</option></select><input v-else :id="'rule-test-'+field.key" v-model="ruleTestValues[field.key]" class="bio-nexus-field" /></BioNexusFormField><button type="button" class="bio-nexus-action bio-nexus-action-primary" @click="runRuleTest">Evaluar reglas</button><div v-if="ruleTestError" class="bio-nexus-message bio-nexus-message-error">{{ ruleTestError }}</div><output v-else-if="ruleTestExecuted" class="rule-test-result"><span>{{ ruleTestMatch }}</span><strong>{{ ruleTestResult === '' ? '[ vacio ]' : ruleTestResult }}</strong></output></section><template #footer><button type="button" class="bio-nexus-action bio-nexus-action-secondary" @click="ruleTestDialog?.close()">Cerrar</button></template></BioNexusDialog><BioNexusDialog ref="formulaTestDialog" size="compact" kicker="Validacion local" title="Probar formula" :subtitle="formulaTestOption || fieldDraft.label"><section class="formula-test-body"><div class="formula-test-expression"><strong>Formula aplicada</strong><code>{{ formulaTestExpression }}</code></div><BioNexusFormField v-for="input in formulaTestInputs" :key="input.key" :label="input.label" :field-id="'formula-test-'+input.key"><template v-if="input.source==='autocomplete'"><select :id="'formula-test-'+input.key" v-model="formulaTestValues[input.key]" class="bio-nexus-field"><option value="">Seleccionar</option><option v-for="option in input.options" :key="option" :value="option">{{ option }}</option></select></template><input v-else :id="'formula-test-'+input.key" v-model="formulaTestValues[input.key]" class="bio-nexus-field" inputmode="decimal" @input="sanitizeTestValue(input.key)" /></BioNexusFormField><button type="button" class="bio-nexus-action bio-nexus-action-primary" @click="runFormulaTest">Calcular resultado</button><div v-if="formulaTestError" class="bio-nexus-message bio-nexus-message-error">{{ formulaTestError }}</div><output v-else-if="formulaTestResult!==null" class="formula-test-result"><span>Resultado</span><strong>{{ formulaTestResult }}</strong></output></section><template #footer><button type="button" class="bio-nexus-action bio-nexus-action-secondary" @click="formulaTestDialog?.close()">Cerrar</button></template></BioNexusDialog>
    </section>
    <template #footer><div class="pilot-note"><strong>Formato persistido en Bio Nexus.</strong><span>Carga y guarda la matriz version 2 del examen seleccionado.</span></div><button type="button" class="bio-nexus-action bio-nexus-action-secondary" @click="requestClose">Cerrar</button><button type="button" class="bio-nexus-action bio-nexus-action-secondary" @click="resetPilot">Restablecer cambios</button><button type="button" class="bio-nexus-action bio-nexus-action-primary" :disabled="!dirty" @click="saveLocal"><BioNexusActionIcon action="save" />Guardar formato</button></template>
  </BioNexusDialog>
</template>
<script setup>
